import {uid,today,validateBackup,money} from './domain.mjs';
import {defaultInvestments,validateInvestments,replayPosition,stockGross,stockKey,stockInt,stockDate,validStockCode} from './investment-schema.mjs';
export const investmentData=state=>state.investments||defaultInvestments();
export function price4(value){const n=Number(value);if(value===null||String(value).trim()===''||!Number.isFinite(n)||n<=0||n>1e6||Math.abs(n*10000-Math.round(n*10000))>0.00001)throw Error('請輸入正確單價，最多4位小數');return Math.round(n*10000);}
export function stockShares(value,unit='shares'){const n=Number(value)*(unit==='lots'?1000:1);if(!['shares','lots'].includes(unit)||!stockInt(n,1,1e9))throw Error('請確認股數與單位；1張為1000股');return n;}
const update=(state,data)=>validateBackup({...state,investments:validateInvestments(data)});
export function savePosition(state,input,id=null){const data=structuredClone(investmentData(state)),old=data.positions.find(p=>p.id===id);if(id&&!old)throw Error('找不到持股');if(old&&data.events.some(e=>e.positionId===id)&&['market','code','openingDate','openingShares','openingCost'].some(k=>input[k]!==old[k]))throw Error('已有交易的持股起點不可直接覆蓋；只能修改名稱與類型，股數請由交易或分割調整核對');const row={...input,id:id||uid()};if(old&&stockKey(old.market,old.code)!==stockKey(row.market,row.code))data.prices=data.prices.filter(q=>stockKey(q.market,q.code)!==stockKey(old.market,old.code));data.positions=id?data.positions.map(p=>p.id===id?row:p):[...data.positions,row];return update(state,data);}
export function saveStockEvent(state,input,id=null){const data=structuredClone(investmentData(state));if(id&&!data.events.some(e=>e.id===id))throw Error('找不到投資交易');const old=data.events.find(e=>e.id===id);const row={...input,id:id||uid(),order:old?.order??Math.max(-1,...data.events.map(e=>e.order))+1};data.events=id?data.events.map(e=>e.id===id?row:e):[...data.events,row];return update(state,data);}
export function deleteStockEvent(state,id){const data=structuredClone(investmentData(state));data.events=data.events.filter(e=>e.id!==id);return update(state,data);}
export function deletePosition(state,id){const data=structuredClone(investmentData(state));if(data.events.some(e=>e.positionId===id))throw Error('這個持股仍有交易，請先核對交易紀錄');const p=data.positions.find(p=>p.id===id);data.positions=data.positions.filter(p=>p.id!==id);data.prices=data.prices.filter(q=>stockKey(q.market,q.code)!==stockKey(p?.market,p?.code));return update(state,data);}
export function saveStockPrice(state,input){const data=structuredClone(investmentData(state)),key=stockKey(input.market,input.code);data.prices=[...data.prices.filter(q=>stockKey(q.market,q.code)!==key),input];return update(state,data);}
export const saveInvestorProfile=(state,profile)=>update(state,{...investmentData(state),profile});
export function validateQuoteFile(raw){if(!raw||raw.version!==1||!stockDate(raw.generatedDate)||!Array.isArray(raw.quotes)||raw.quotes.length>20000)throw Error('行情檔格式不正確');const seen=new Set();const quotes=raw.quotes.map(q=>{const key=stockKey(q?.market,q?.code);if(!['TWSE','TPEX'].includes(q?.market)||!validStockCode(q.code)||typeof q.name!=='string'||q.name.length>80||!stockDate(q.date)||!stockInt(q.price4,1,1e10)||seen.has(key))throw Error('行情資料欄位不正確');seen.add(key);return {market:q.market,code:q.code,name:q.name,date:q.date,price4:q.price4,source:q.market==='TWSE'?'TWSE':'TPEX'};});return {version:1,generatedDate:raw.generatedDate,quotes,sources:Array.isArray(raw.sources)?raw.sources.filter(s=>s&&['TWSE','TPEX'].includes(s.market)).map(s=>({market:s.market,status:typeof s.status==='string'?s.status.slice(0,120):'',date:stockDate(s.date)?s.date:null})):[]};}
export function portfolio(state,quotes=[]){const data=investmentData(state),map=new Map(quotes.map(q=>[stockKey(q.market,q.code),q]));for(const q of data.prices){const key=stockKey(q.market,q.code),old=map.get(key);if(!old||old.date<=q.date)map.set(key,q);}const rows=data.positions.map(p=>{const stats=replayPosition(p,data.events),quote=map.get(stockKey(p.market,p.code))||null,value=stats.shares&&quote?stockGross(stats.shares,quote.price4):stats.shares?null:0;return {...p,...stats,quote,value,unrealized:value!==null&&stats.cost!==null?value-stats.cost:null};});const held=rows.filter(r=>r.shares>0),missingPrices=held.filter(r=>r.value===null).length,missingCost=held.filter(r=>r.cost===null).length,unknownSales=rows.reduce((n,r)=>n+r.unknownSales,0),knownValue=held.reduce((n,r)=>n+(r.value||0),0),knownCost=held.reduce((n,r)=>n+(r.cost||0),0),dividends=rows.reduce((n,r)=>n+r.dividends,0),realizedKnown=rows.reduce((n,r)=>n+r.realizedKnown,0),unrealized=missingPrices||missingCost?null:held.reduce((n,r)=>n+r.unrealized,0),realized=unknownSales?null:realizedKnown;return {rows,held,missingPrices,missingCost,unknownSales,knownValue,knownCost,value:missingPrices?null:knownValue,unrealized,realized,dividends,totalGain:unrealized===null||realized===null?null:unrealized+realized+dividends,fees:rows.reduce((n,r)=>n+r.fees,0),profile:data.profile};}
export function coachFacts(state,quotes=[]){const p=portfolio(state,quotes),full=p.value!==null&&p.value>0,largest=full?[...p.held].sort((a,b)=>b.value-a.value)[0]:null,weight=largest?largest.value/p.value*100:null;const findings=[];if(!p.held.length)findings.push('先建立持股或匯入截圖，再看配置。');if(p.missingPrices)findings.push(`${p.missingPrices}個持股缺價格，尚不能完整比較配置。`);if(p.missingCost||p.unknownSales)findings.push('部分成本或歷史賣出成本未知，總報酬尚不能完整計算。');if(weight!==null&&weight>p.profile.concentration)findings.push(`${largest.name}占目前持股市值${weight.toFixed(1)}%，超過你設定的${p.profile.concentration}%集中度提醒門檻。`);if(p.held.some(r=>r.quote&&r.quote.date<today()))findings.push('價格為指定日期的收盤價或手動報價，不是即時行情。');if(!findings.length)findings.push('依目前資料，沒有超過你設定的集中度提醒門檻；這不代表沒有投資風險。');return {portfolio:p,largest:largest?.code||null,weight,findings,options:[{title:'維持配置／保留資金',text:'先保留本月預算，補齊成本、費用與目標；不需要為了完成記錄而立即交易。'},{title:'用新增資金調整',text:'先試算新增資金分配對比重的影響；只有一個標的時，買進未必能降低集中度。投入前先核對預算。'},{title:'評估減碼再調整',text:'試算賣出對持股比例的影響，並填入實際手續費與稅費；不以配息金額取代總報酬。'}]};}
export function investmentScenario(state,quotes,{positionId,side,shares,fee=0,tax=0,executionPrice4}){const p=portfolio(state,quotes),row=p.rows.find(r=>r.id===positionId);if(!row||!['buy','sell'].includes(side)||!stockInt(shares,1,1e9)||!stockInt(fee)||!stockInt(tax))throw Error('請確認試算股數與費用');const px=executionPrice4||row.quote?.price4;if(!px)throw Error('沒有價格，請先補上手動報價');if(side==='sell'&&shares>row.shares)throw Error('試算賣出不可超過持股');if(p.missingPrices)throw Error('請先補齊所有持股價格，才能比較配置');const gross=stockGross(shares,px),cashChange=side==='buy'?-gross-fee:gross-fee-tax,afterShares=row.shares+(side==='buy'?shares:-shares),afterValue=afterShares?stockGross(afterShares,row.quote?.price4||px):0,total=p.knownValue-(row.value||0)+afterValue;return {beforeWeight:p.knownValue?(row.value||0)/p.knownValue*100:0,afterWeight:total?afterValue/total*100:0,cashChange,afterShares,total,overBudget:side==='buy'&&p.profile.monthlyBudget>0&&-cashChange>p.profile.monthlyBudget};}
export const stockEventKey=e=>JSON.stringify([e.positionId,e.date,e.type,e.shares??null,e.price4??null,e.fee??0,e.tax??0,e.amount??null,e.sharesAfter??null]);
export function importStockRows(state,rows){
  if(!Array.isArray(rows)||rows.length>120)throw Error('一次最多核對120筆');
  const snapshots=new Map();for(const r of rows.filter(r=>r.type==='snapshot')){const key=stockKey(r.market,r.code),old=snapshots.get(key);if(old&&JSON.stringify([old.date,old.shares,old.cost])!==JSON.stringify([r.date,r.shares,r.cost]))throw Error('同一股票有多份不同持股庫存，請只選一份作起點');snapshots.set(key,r);}
  for(const r of rows.filter(r=>r.type!=='snapshot'&&r.type!=='dividend')){const initial=snapshots.get(stockKey(r.market,r.code));if(initial&&r.date<=initial.date)throw Error('成交／股利日期不晚於這份庫存起點，可能已包含在截圖，請分開核對');}
  let next=state,duplicates=0;for(const r of [...rows].sort((a,b)=>Number(b.type==='snapshot')-Number(a.type==='snapshot')||a.date.localeCompare(b.date))){const data=investmentData(next),existing=data.positions.find(p=>p.market===r.market&&p.code===r.code);if(r.type==='snapshot'){if(existing){duplicates++;continue;}next=savePosition(next,{market:r.market,code:r.code,name:r.name,kind:r.kind,openingDate:r.date,openingShares:r.shares,openingCost:r.cost});continue;}let id=existing?.id;if(!id){next=savePosition(next,{market:r.market,code:r.code,name:r.name,kind:r.kind,openingDate:r.date,openingShares:0,openingCost:0});id=investmentData(next).positions.at(-1).id;}const event={positionId:id,date:r.date,type:r.type,shares:r.shares,price4:r.price4,fee:r.fee||0,tax:r.tax||0,amount:r.amount};if(investmentData(next).events.some(e=>stockEventKey(e)===stockEventKey(event))&&!r.allowDuplicate){duplicates++;continue;}next=saveStockEvent(next,event);}return {state:next,duplicates};}
